// File layout under .attesso/:
//   key.json     Ed25519 key pair, 0600, generated by init
//   policy.json  the bounds this project allows
//   ledger.jsonl one signed entry per line
//   config.json  the recorded head (count + hash), the only thing that makes a
//                truncated log visible
//   lock         held while appending, so two agents cannot interleave writes
//   details/     local action previews, never synced
import { randomBytes } from 'node:crypto';
import { channel } from 'node:diagnostics_channel';
import { closeSync, chmodSync, existsSync, fsyncSync, ftruncateSync, linkSync, lstatSync, mkdirSync, openSync, readFileSync, readSync, renameSync, statSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { buildEntry, entryHash, newSigningKey, signEntry, verifyEntry, verifyHead, verifyStep } from './ledger.mjs';
import { DEFAULT_TOOLS, loadTools } from './classify.mjs';
import { decide } from './decide.mjs';
import { parseLine, parseTail } from './jsonl.mjs';
import { ENGINE_VERSION } from './version.mjs';
import { policyDigest, validatePolicy } from './policy.mjs';
import { rulesDigest, rulesForProfile, validateRules } from './rules.mjs';
import { toolGate, manifestDigest, toolsDigest } from './toolpin.mjs';
import { evaluatePathScope, validatePathsConfig } from './fs-paths.mjs';
import { captureDetail, MAX_DETAIL_BYTES } from './detail.mjs';
import { forEachEntry, forEachEntrySync } from './stream.mjs';

export function paths(dir) {
  return {
    dir,
    key: join(dir, 'key.json'),
    policy: join(dir, 'policy.json'),
    rules: join(dir, 'rules.json'),
    fsPaths: join(dir, 'paths.json'),
    uiIndex: join(dir, 'ui-index.json'),
    ledger: join(dir, 'ledger.jsonl'),
    config: join(dir, 'config.json'),
    run: join(dir, 'run.json'),
    details: join(dir, 'details'),
    lock: join(dir, 'lock'),
    policies: join(dir, 'policies'),
    tools: join(dir, 'tools.json'),
    toolLock: join(dir, 'tools.lock.json'),
    toolsSnapshots: join(dir, 'tools'),
    mcpSnapshots: join(dir, 'mcp'),
  };
}

const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'));

// In-process monitoring: no dependency, no output, no cost when nobody listens.
const decisionChannel = channel('bounds.decision');

function publishDecision(entry) {
  if (!decisionChannel.hasSubscribers) return;
  try {
    decisionChannel.publish({
      seq: entry.seq,
      at: entry.at,
      action: entry.action,
      decision: entry.decision,
      code: entry.code,
      rule: entry.rule ?? null,
      capability: entry.capability ?? null,
      trust: entry.trust ?? null,
      args_hash: entry.args_hash ?? null,
      policy_digest: entry.policy_digest,
      rules_digest: entry.rules_digest ?? null,
      tools_digest: entry.tools_digest ?? null,
      tool_pin: entry.tool_pin ?? null,
      mcp_digest: entry.mcp_digest ?? null,
      entry_hash: entryHash(entry),
      kid: entry.kid,
    });
  } catch {
    // publish runs subscribers synchronously; a subscriber that throws is a bug
    // in the subscriber, not a reason to fail the decision that was recorded.
  }
}

function writeJson(path, value) {
  const temporary = `${path}.${process.pid}.tmp`;
  const text = `${JSON.stringify(value, null, 2)}\n`;
  const handle = openSync(temporary, 'w', 0o600);
  try {
    writeFileSync(handle, text);
    fsyncSync(handle);
  } finally {
    closeSync(handle);
  }
  renameSync(temporary, path);
  fsyncDir(dirname(path));
}

function writeEntry(file, entry) {
  const handle = openSync(file.ledger, 'a', 0o600);
  try {
    writeFileSync(handle, `${JSON.stringify(entry)}\n`);
    fsyncSync(handle);
  } finally {
    closeSync(handle);
  }
}

function readAt(fd, buffer, position) {
  let offset = 0;
  while (offset < buffer.length) {
    const bytes = readSync(fd, buffer, offset, buffer.length - offset, position + offset);
    if (bytes === 0) break;
    offset += bytes;
  }
  return offset;
}

// A crash can leave a line without its newline. A parseable line is kept (its
// signature still decides whether it counts); an unparseable tail was never an
// entry and is dropped. The head count is untouched, so a real truncation still
// fails the append instead of being papered over. This reads backwards so an
// old ledger is not loaded into memory just to repair its last line.
function repairTornTail(file) {
  const size = statSync(file.ledger).size;
  if (size === 0) return;
  const fd = openSync(file.ledger, 'r+');
  try {
    const last = Buffer.alloc(1);
    readAt(fd, last, size - 1);
    if (last[0] === 0x0a) return;

    let newline = -1;
    let end = size - 1;
    while (end >= 0 && newline === -1) {
      const start = Math.max(0, end - 64 * 1024 + 1);
      const chunk = Buffer.alloc(end - start + 1);
      readAt(fd, chunk, start);
      const at = chunk.lastIndexOf(0x0a);
      if (at !== -1) newline = start + at;
      end = start - 1;
    }
    const cut = newline + 1;
    const tail = Buffer.alloc(size - cut);
    readAt(fd, tail, cut);
    let complete = false;
    try {
      JSON.parse(tail.toString('utf8'));
      complete = true;
    } catch {
      // The tail is a partial write, not an entry.
    }
    if (complete) {
      const handle = openSync(file.ledger, 'a', 0o600);
      try {
        writeFileSync(handle, '\n');
        fsyncSync(handle);
      } finally {
        closeSync(handle);
      }
      return;
    }
    ftruncateSync(fd, cut);
    fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
}

// A rename is durable once the directory entry is flushed; Windows cannot open a
// directory for fsync, so this is best-effort there.
function fsyncDir(path) {
  let handle;
  try {
    handle = openSync(path, 'r');
    fsyncSync(handle);
  } catch {
    // Directory fsync is unavailable on this platform; the file fsync still ran.
  } finally {
    if (handle !== undefined) closeSync(handle);
  }
}

// A decision names the exact policy and rules bytes that judged it, so a receipt
// can carry them later. Content addressed, written once, never rewritten.
const snapshotBase = (dir, kind) => (kind === 'tools' ? paths(dir).toolsSnapshots : paths(dir).policies);
const snapshotFile = (dir, digest, kind) => join(snapshotBase(dir, kind), `${digest}.json`);

function writeSnapshot(dir, digest, value, kind = 'policy') {
  const file = snapshotFile(dir, digest, kind);
  if (existsSync(file)) return;
  mkdirSync(snapshotBase(dir, kind), { recursive: true, mode: 0o700 });
  writeJson(file, value);
}

export function readToolLock(dir) {
  const file = paths(dir).toolLock;
  return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : null;
}

export function writeToolLock(dir, lock) {
  return withLock(dir, () => {
    writeJson(paths(dir).toolLock, lock);
    return lock;
  });
}

export function writeMcpManifest(dir, manifest) {
  const digest = manifestDigest(manifest);
  writeSnapshot(dir, digest, manifest, 'mcp');
  return digest;
}

export function isInitialised(dir) {
  return existsSync(paths(dir).key);
}

export function readKey(dir) {
  return readJson(paths(dir).key);
}

export function readConfig(dir) {
  return readJson(paths(dir).config);
}

// The run state file holds the live pointer and the last closed run, so the
// status endpoint reads one small file instead of scanning the log. The signed
// run.start and run.end entries remain the record.
function readRunFile(dir) {
  const file = paths(dir).run;
  if (!existsSync(file)) return null;
  const value = readJson(file);
  if (value === null || typeof value !== 'object' || value.version !== 1) throw new Error('run.json is malformed');
  if (value.active !== undefined && value.active !== null) {
    const active = value.active;
    if (
      typeof active !== 'object'
      || typeof active.id !== 'string'
      || active.id === ''
      || typeof active.started_at !== 'string'
      || active.started_at === ''
    ) {
      throw new Error('run.json is malformed');
    }
  }
  if (
    value.active === undefined
    && (typeof value.id !== 'string' || value.id === '' || typeof value.started_at !== 'string' || value.started_at === '')
  ) {
    throw new Error('run.json is malformed');
  }
  return value;
}

export function readActiveRun(dir) {
  const value = readRunFile(dir);
  if (value === null) return null;
  if (value.active === undefined) return value; // legacy flat active run
  return value.active;
}

export function readLastRun(dir) {
  const value = readRunFile(dir);
  if (value === null || value.last === undefined || value.last === null) return null;
  const last = value.last;
  if (typeof last !== 'object' || typeof last.id !== 'string' || last.id === '') throw new Error('run.json is malformed');
  return last;
}

export function writeActiveRun(dir, value) {
  writeJson(paths(dir).run, value);
}

export function clearActiveRun(dir) {
  try {
    unlinkSync(paths(dir).run);
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
}

// The detail is a local sidecar keyed by the signed entry's sequence. The
// signed entry carries its hash; this store never syncs or bundles the file.
export function writeDetail(dir, seq, detail) {
  if (!Number.isInteger(seq) || seq < 1) throw new Error('detail seq must be a positive integer');
  if (!detail || typeof detail !== 'object' || Array.isArray(detail) || detail.seq !== seq) {
    throw new Error('detail does not match its sequence');
  }
  const folder = paths(dir).details;
  mkdirSync(folder, { recursive: true, mode: 0o700 });
  try {
    chmodSync(folder, 0o700);
  } catch {
    // A store on a filesystem without POSIX modes still works; the file mode
    // below is the strongest guarantee that filesystem can give.
  }
  const file = join(folder, `${seq}.json`);
  const temp = join(folder, `.tmp-${process.pid}-${randomBytes(8).toString('hex')}`);
  try {
    writeFileSync(temp, `${JSON.stringify(detail, null, 2)}\n`, { mode: 0o600, flag: 'wx' });
    renameSync(temp, file);
  } catch (error) {
    try {
      unlinkSync(temp);
    } catch {
      // The temp file may never have been created; the write error is the
      // error the caller needs.
    }
    throw error;
  }
  return file;
}

export function readDetail(dir, seq) {
  if (!Number.isInteger(seq) || seq < 1) throw new Error('detail seq must be a positive integer');
  const file = join(paths(dir).details, `${seq}.json`);
  let stats;
  try {
    stats = lstatSync(file);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
  if (stats.isSymbolicLink() || !stats.isFile() || stats.size > MAX_DETAIL_BYTES * 4) {
    throw new Error('detail file is not a small regular file');
  }
  const raw = readFileSync(file, 'utf8');
  const detail = JSON.parse(raw);
  // The writer emits this exact form. A hand-edited file, including one with a
  // duplicate key that JSON.parse would collapse, is not the file that was
  // hashed, so it is refused instead of silently reinterpreted.
  if (JSON.stringify(detail, null, 2) !== raw.trimEnd()) {
    throw new Error('detail file is not in its written form');
  }
  if (!detail || typeof detail !== 'object' || Array.isArray(detail) || detail.seq !== seq) {
    throw new Error('detail file does not match its sequence');
  }
  return detail;
}

export function deleteDetail(dir, seq) {
  if (!Number.isInteger(seq) || seq < 1) throw new Error('detail seq must be a positive integer');
  try {
    unlinkSync(join(paths(dir).details, `${seq}.json`));
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
}

export function readSnapshot(dir, digest, kind = 'policy') {
  const file = snapshotFile(dir, digest, kind);
  if (!existsSync(file)) throw new Error(`SNAPSHOT_MISSING: ${kind} ${digest} was not archived with this entry`);
  return readJson(file);
}

export function init(dir, { profile = 'balanced' } = {}) {
  if (isInitialised(dir)) {
    throw new Error(`${dir} already holds a ledger; refusing to replace its key`);
  }
  const rules = rulesForProfile(profile);
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  return withLock(dir, () => {
    // Two processes that saw an empty directory must not both create a key.
    // The first one wins; the second sees the key under the same lock.
    if (isInitialised(dir)) {
      throw new Error(`${dir} already holds a ledger; refusing to replace its key`);
    }
    const file = paths(dir);
    const key = newSigningKey();
    // Record everything by default and let rules.json decide: a policy that names
    // one action refuses every other action, so a fresh install could not log the
    // very commands its own README shows.
    writeJson(file.policy, {
      version: 1,
      action: '*',
    });
    writeJson(file.config, { version: 1, head: { count: 0, hash: 'genesis' }, engine: ENGINE_VERSION });
    writeJson(file.tools, DEFAULT_TOOLS);
    writeJson(file.rules, rules);
    writeFileSync(file.ledger, '', { mode: 0o600 });
    // The key is the readiness marker; writing it last means a crash during init
    // leaves a directory that is still uninitialised, not one that half works.
    writeJson(file.key, { version: 1, kid: key.kid, public: key.publicPem, private: key.privatePem });
    return { dir, kid: key.kid, profile };
  });
}

// An existing ledger can adopt a shipped profile without touching its key,
// head or entries. The previous rules stay beside the ledger for rollback.
export function setRulesProfile(dir, profile = 'balanced') {
  const next = rulesForProfile(profile);
  validateRules(next);
  return withLock(dir, () => {
    const file = paths(dir);
    const previous = existsSync(file.rules) ? readFileSync(file.rules, 'utf8') : null;
    const previousDigest = previous === null ? undefined : rulesDigest(JSON.parse(previous));
    const nextDigest = rulesDigest(next);
    if (previousDigest === nextDigest) {
      return { profile, changed: false, previous: previousDigest, digest: nextDigest };
    }
    if (previous !== null) renameSync(file.rules, `${file.rules}.bak`);
    writeJson(file.rules, next);
    return { profile, changed: true, previous: previousDigest, digest: nextDigest };
  });
}

// One rule, one file: a run budget is an ordinary rule, so replay, the digest
// and the refusal all see exactly what the hook enforces.
export function setRunBudget(dir, { tokens, usd, enforce = false, off = false } = {}) {
  if (off && (tokens !== undefined || usd !== undefined)) {
    throw new Error('--off takes no budget values');
  }
  if (tokens !== undefined && typeof tokens !== 'string' && typeof tokens !== 'number') {
    throw new Error('--tokens needs a value');
  }
  if (usd !== undefined && typeof usd !== 'string' && typeof usd !== 'number') {
    throw new Error('--usd needs a value');
  }
  const tokenLimit = tokens === undefined ? undefined : Number(tokens);
  if (tokenLimit !== undefined && (!Number.isInteger(tokenLimit) || tokenLimit < 1)) {
    throw new Error('--tokens must be a whole number of at least 1');
  }
  const usdLimit = usd === undefined ? undefined : Number(usd);
  if (usdLimit !== undefined && (!Number.isFinite(usdLimit) || usdLimit <= 0)) {
    throw new Error('--usd must be a positive number');
  }
  if (!off && tokenLimit === undefined && usdLimit === undefined) {
    throw new Error('a budget needs --tokens or --usd');
  }
  return withLock(dir, () => {
    const file = paths(dir);
    const current = existsSync(file.rules)
      ? JSON.parse(readFileSync(file.rules, 'utf8'))
      : { version: 1, rules: [] };
    if (!Array.isArray(current.rules)) throw new Error('rules.json has no rules list');
    const others = current.rules.filter((rule) => rule.id !== 'run-budget');
    let next;
    if (off) {
      next = { ...current, rules: others };
    } else {
      const rule = { id: 'run-budget', deny: { capabilities: ['execute', 'write', 'send'] } };
      if (tokenLimit !== undefined) rule.max_tokens = tokenLimit;
      if (usdLimit !== undefined) rule.max_cost_usd = usdLimit;
      if (enforce) rule.enforce = true;
      next = { ...current, rules: [rule, ...others] };
    }
    validateRules(next);
    const previous = existsSync(file.rules) ? readFileSync(file.rules, 'utf8') : null;
    const previousDigest = previous === null ? undefined : rulesDigest(JSON.parse(previous));
    const nextDigest = rulesDigest(next);
    if (previousDigest === nextDigest) {
      return { changed: false, digest: nextDigest, rule: next.rules.find((rule) => rule.id === 'run-budget') };
    }
    if (previous !== null) renameSync(file.rules, `${file.rules}.bak`);
    writeJson(file.rules, next);
    return { changed: true, digest: nextDigest, rule: next.rules.find((rule) => rule.id === 'run-budget') };
  });
}

// The page reads the same rule the hook enforces; no second budget store.
export function readRunBudget(dir) {
  const file = paths(dir);
  if (!existsSync(file.rules)) return null;
  const rules = JSON.parse(readFileSync(file.rules, 'utf8'));
  validateRules(rules);
  const rule = (rules.rules ?? []).find((item) => item.id === 'run-budget');
  if (!rule) return null;
  return {
    tokens: Number.isInteger(rule.max_tokens) ? rule.max_tokens : null,
    usd: typeof rule.max_cost_usd === 'number' ? rule.max_cost_usd : null,
    enforce: rule.enforce === true,
  };
}

export function readState(dir) {
  const file = paths(dir);
  return {
    key: readJson(file.key),
    config: readJson(file.config),
    policy: readJson(file.policy),
    rules: existsSync(file.rules) ? readJson(file.rules) : null,
    entries: readEntries(dir),
  };
}

export function readEntries(dir) {
  const text = readFileSync(paths(dir).ledger, 'utf8');
  if (text === '') return [];
  const lines = text.split('\n');
  const trailing = lines.pop();
  const entries = lines.map((line, index) => parseLine(line, index + 1));
  // A reader can catch an append mid-line. A partial tail is not an entry and
  // is ignored; the recorded head still makes a real truncation visible.
  if (trailing !== '') {
    const entry = parseTail(trailing, lines.length + 1);
    if (entry !== undefined) entries.push(entry);
  }
  return entries;
}

// Stream the same checks verifyChain performs over an array. This is the
// path that keeps a year-old ledger from being loaded into memory at once.
export async function verifyLedger(dir) {
  const file = paths(dir);
  let key;
  let head;
  try {
    key = readKey(dir);
    head = readConfig(dir).head;
  } catch (error) {
    return { ok: false, reason: error.message };
  }
  let previous = 'genesis';
  let count = 0;
  let verified = 0;
  let ignoredTail = false;
  try {
    await forEachEntry(
      file.ledger,
      (entry, index) => {
        const step = verifyStep(entry, index - 1, previous, key.public);
        if (!step.ok) throw new Error(step.reason);
        previous = step.hash;
        count = index;
        verified = index;
      },
      {
        onIgnoredTail: () => {
          ignoredTail = true;
        },
      },
    );
  } catch (error) {
    return { ok: false, reason: error.message, kid: key.kid, verified, ignoredTail };
  }
  return { ...verifyHead(count, previous, head), kid: key.kid, count, verified, ignoredTail };
}

function processAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

// A writer waits for a live holder instead of failing the decision. The process
// is short-lived, so a synchronous sleep is the simplest correct backoff.
function sleepSync(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

// A burst of agents can queue behind one append. Five seconds dropped 78 of
// 100 decisions in observe mode, silently; a minute records all of them and
// still fails closed when the store is genuinely stuck.
const LOCK_WAIT_MS = () => Number(process.env.ATTESSO_LOCK_WAIT_MS ?? 60000);
const LOCK_RETRY_MS = 25;

// Create the lock with its owner already inside, then link it into place. A
// plain O_EXCL create leaves an empty file for a moment, and a waiter that reads
// it in that window would reclaim a live lock. The token lets the holder remove
// only its own lock, never one a later process created after reclaiming it.
function acquireLock(lock) {
  const token = `${process.pid}.${randomBytes(6).toString('hex')}`;
  const candidate = `${lock}.${token}`;
  const handle = openSync(candidate, 'wx', 0o600);
  try {
    writeFileSync(handle, token);
    fsyncSync(handle);
  } finally {
    closeSync(handle);
  }
  try {
    linkSync(candidate, lock);
    return token;
  } catch (error) {
    if (error.code === 'EEXIST') return null;
    throw error;
  } finally {
    try {
      unlinkSync(candidate);
    } catch {
      // The candidate was already removed; the lock name is what matters.
    }
  }
}

// Serialize stale-lock reclamation. Without this claim two writers can both
// decide a dead lock is stale; one takes the lock and the other then unlinks
// the live lock, letting two writers append the same seq. Only the claim
// owner re-reads and removes the stale lock.
function claimReclaim(reclaim) {
  const token = `${process.pid}.${randomBytes(6).toString('hex')}`;
  const candidate = `${reclaim}.${token}`;
  const handle = openSync(candidate, 'wx', 0o600);
  try {
    writeFileSync(handle, token);
    fsyncSync(handle);
  } finally {
    closeSync(handle);
  }
  try {
    linkSync(candidate, reclaim);
    return true;
  } catch (error) {
    if (error.code === 'EEXIST') return false;
    throw error;
  } finally {
    try {
      unlinkSync(candidate);
    } catch {
      // The candidate was already removed; the claim name is what matters.
    }
  }
}

function withLock(dir, run) {
  const { lock } = paths(dir);
  const deadline = Date.now() + LOCK_WAIT_MS();
  for (;;) {
    const token = acquireLock(lock);
    if (token) {
      try {
        return run();
      } finally {
        try {
          if (readFileSync(lock, 'utf8').trim() === token) unlinkSync(lock);
        } catch {
          // The lock is already gone; nothing to undo.
        }
      }
    }
    let raw = '';
    try {
      raw = readFileSync(lock, 'utf8').trim();
    } catch {
      // The holder released it between link and read; retry immediately.
      continue;
    }
    const holder = Number(raw.split('.')[0]);
    if (raw === '' || !Number.isInteger(holder) || holder <= 0) {
      throw new Error(`the ledger lock at ${lock} has no owner; remove it if no attesso process is running`);
    }
    if (!processAlive(holder)) {
      // Only the claim owner may judge and unlink the lock it read. A second
      // writer that also saw the stale pid waits here instead of removing a
      // lock a new holder just created.
      const reclaim = `${lock}.reclaim`;
      if (!claimReclaim(reclaim)) {
        try {
          const claimRaw = readFileSync(reclaim, 'utf8').trim();
          const claimPid = Number(claimRaw.split('.')[0]);
          if (Number.isInteger(claimPid) && claimPid > 0 && !processAlive(claimPid)) {
            unlinkSync(reclaim);
          }
        } catch {
          // The claim released or was removed; the next iteration re-reads.
        }
        sleepSync(LOCK_RETRY_MS + Math.floor(Math.random() * LOCK_RETRY_MS));
        continue;
      }
      try {
        let current = '';
        try {
          current = readFileSync(lock, 'utf8').trim();
        } catch {
          continue;
        }
        if (current === raw) {
          try {
            unlinkSync(lock);
          } catch {
            // Another writer reclaimed it first; the next iteration takes it.
          }
        }
      } finally {
        try {
          unlinkSync(reclaim);
        } catch {
          // The claim is already gone; nothing to release.
        }
      }
      continue;
    }
    if (Date.now() >= deadline) {
      throw new Error(`another attesso process (pid ${holder}) holds the ledger; retry when it finishes`);
    }
    sleepSync(LOCK_RETRY_MS + Math.floor(Math.random() * LOCK_RETRY_MS));
  }
}

export function withLedgerLock(dir, run) {
  return withLock(dir, run);
}

// A crash can leave signed lines whose head update never landed. Verify the
// tail while collecting only the task history the rules need, so append does
// not hold the whole ledger in memory.
function reconcileHead(dir, head, task, publicPem) {
  let count = 0;
  let lastHash = head.hash;
  const history = [];
  forEachEntrySync(paths(dir).ledger, (entry, index) => {
    count = index;
    if (index > head.count) {
      if (entry.seq !== index) throw new Error(`entry ${index} carries seq ${entry.seq}`);
      if (entry.prev !== lastHash) throw new Error(`entry ${entry.seq} does not chain to the entry before it`);
      if (!verifyEntry(entry, publicPem)) throw new Error(`entry ${entry.seq} signature does not verify`);
      lastHash = entryHash(entry);
    }
    if ((entry.task ?? null) === (task ?? null)) history.push(entry);
  });
  if (count < head.count) {
    throw new Error(`config records ${head.count} entries, the log holds ${count}; the ledger was truncated`);
  }
  if (count === head.count) return { head, history };
  const repaired = { count, hash: lastHash };
  const previousConfig = readJson(paths(dir).config);
  writeJson(paths(dir).config, {
    version: 1,
    head: repaired,
    engine: previousConfig?.engine ?? ENGINE_VERSION,
  });
  return { head: repaired, history };
}

export function append(dir, proposal, { now = new Date(), control, verdict: forcedVerdict } = {}) {
  return withLock(dir, () => {
    const file = paths(dir);
    repairTornTail(file);
    const key = readJson(file.key);
    const config = readJson(file.config);
    const policy = validatePolicy(readJson(file.policy));
    const rules = existsSync(file.rules) ? validateRules(readJson(file.rules)) : null;
    const pathConfig = existsSync(file.fsPaths) ? validatePathsConfig(readJson(file.fsPaths)) : null;
    const activeRun = readActiveRun(dir);
    const runId = typeof proposal.run_id === 'string' && proposal.run_id !== '' ? proposal.run_id : activeRun?.id;
    const tools = loadTools(dir);
    const toolsHash = toolsDigest(tools);
    const toolLock = readToolLock(dir);
    const toolHash =
      typeof proposal.tool_hash === 'string' && proposal.tool_hash !== ''
        ? proposal.tool_hash
        : typeof proposal.tool_definition_hash === 'string' && proposal.tool_definition_hash !== ''
          ? proposal.tool_definition_hash
          : undefined;
    const mcpDigest =
      typeof proposal.mcp_digest === 'string' && proposal.mcp_digest !== '' ? proposal.mcp_digest : undefined;
    const toolVerdict = toolGate(toolLock, toolsHash, { ...proposal, tool_hash: toolHash });
    const policyHash = policyDigest(policy);
    const rulesHash = rules ? rulesDigest(rules) : undefined;
    const reconciled = reconcileHead(dir, config.head, proposal.task ?? null, key.public);
    const head = reconciled.head;
    const history = reconciled.history;
    const controlVerdict = control
      ? {
          decision: 'DENY',
          code: control.mode === 'stop' ? 'TASK_STOPPED' : 'TASK_PAUSED',
          rule: `control.${control.mode}`,
        }
      : null;
    const pathVerdict = pathConfig ? evaluatePathScope(pathConfig, proposal) : null;
    const decisionProposal = runId === undefined ? proposal : { ...proposal, run_id: runId };
    const verdict = forcedVerdict ?? controlVerdict ?? toolVerdict ?? pathVerdict ?? decide({ policy, rules, history, proposal: decisionProposal, now });
    const toolPin = toolLock
      ? (toolVerdict?.tool_pin ?? (toolHash ? 'verified' : 'unverified'))
      : undefined;
    const meta = { ...(proposal.meta ?? {}) };
    const argsHash = proposal.args_hash ?? meta.args_hash;
    delete meta.args_hash;
    const seq = head.count + 1;
    const at = now.toISOString();
    let detailHashValue;
    let detailState;
    if (proposal.detail_input !== undefined) {
      try {
        const captured = captureDetail({
          seq,
          at,
          action: proposal.action,
          tool: proposal.subject,
          input: proposal.detail_input,
        });
        writeDetail(dir, seq, captured.detail);
        detailHashValue = captured.hash;
      } catch {
        // The detail is the eyes, not the gate: a capture or write failure
        // records the decision without a preview instead of blocking the call.
        detailHashValue = undefined;
        detailState = 'unavailable';
      }
    }
    if (detailState !== undefined) meta.detail = detailState;
    const entry = buildEntry({
      seq,
      prev: head.hash,
      action: proposal.action,
      subject: proposal.subject,
      amount: proposal.amount,
      meta,
      task: proposal.task,
      runId,
      trust: proposal.trust,
      capability: proposal.capability,
      decision: verdict.decision,
      code: verdict.code,
      rule: verdict.rule,
      taintedBy: verdict.tainted_by,
      enforce: verdict.enforce,
      argsHash,
      detailHash: detailHashValue,
      policyDigest: policyHash,
      rulesDigest: rulesHash,
      toolsDigest: toolsHash,
      toolHash,
      toolPin,
      mcpDigest,
      control,
      kid: key.kid,
      at,
    });
    entry.sig = signEntry(entry, key.private);
    writeSnapshot(dir, policyHash, policy);
    if (rules) writeSnapshot(dir, rulesHash, rules);
    writeSnapshot(dir, toolsHash, tools, 'tools');
    writeEntry(file, entry);
    writeJson(file.config, {
      version: 1,
      head: { count: seq, hash: entryHash(entry) },
      engine: config?.engine ?? ENGINE_VERSION,
    });
    publishDecision(entry);
    return entry;
  });
}

// appendUsage records measured model usage. It is not a policy decision, so it
// skips evaluation and is always ALLOW; the tool-call readers filter it out by
// action and the usage readers join it to the task like any other report.
export function appendUsage(dir, { task, model, inputTokens = 0, outputTokens = 0, cachedTokens = 0, costUsd = 0 } = {}, { now = new Date() } = {}) {
  const tokens = [inputTokens, outputTokens, cachedTokens, costUsd];
  if (tokens.some((value) => typeof value !== 'number' || !Number.isFinite(value) || value < 0)) {
    throw new Error('usage values must be non-negative numbers');
  }
  if (task !== undefined && (typeof task !== 'string' || task.length > 128)) {
    throw new Error('usage task must be a string of at most 128 characters');
  }
  if (model !== undefined && (typeof model !== 'string' || model.length > 100)) {
    throw new Error('usage model must be a string of at most 100 characters');
  }
  const usage = {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cached_tokens: cachedTokens,
    cost_usd: costUsd,
  };
  if (model !== undefined) usage.model = model;
  return append(dir, {
    action: 'llm.session',
    subject: model ?? 'model',
    task,
    capability: 'model',
    meta: { usage },
  }, {
    now,
    verdict: { decision: 'ALLOW', code: 'ALLOW', rule: 'usage.reported' },
  });
}
